for _target in TOOL_TARGETS:
    # Aliases are controlled discovery names. They resolve to the stable ID and
    # therefore share the identical entitlement/readiness policy; display labels
    # and unregistered strings never create new permissions.
    _target.setdefault("aliases", list(_TARGET_ALIASES.get(_target["tool_id"], [])))

_BY_ID = {row["tool_id"]: row for row in TOOL_TARGETS}
_BY_NAME = {row["canonical_name"].casefold(): row for row in TOOL_TARGETS}
_alias_candidates: dict[str, list[dict[str, Any]]] = {}
for _row in TOOL_TARGETS:
    for _alias in _row.get("aliases", []):
        _alias_key = str(_alias).strip().casefold()
        if _alias_key:
            _alias_candidates.setdefault(_alias_key, []).append(_row)
# Ambiguous aliases are excluded rather than silently choosing a capability.
_BY_ALIAS = {alias: rows[0] for alias, rows in _alias_candidates.items() if len(rows) == 1}


def _resolve_target(token: str) -> dict[str, Any] | None:
    label = str(token or "").strip()
    key = label.casefold()
    return _BY_ID.get(label.upper()) or _BY_NAME.get(key) or _BY_ALIAS.get(key)


def _normalize_known_tier(value: str | None) -> str | None:
    """Use the shared fail-closed entitlement parser instead of a second policy."""
    from shoir_tier_capabilities import normalize_tier
    resolved = normalize_tier(value)
    return resolved if resolved in TOOL_TIER_ORDER else None

def get_target_tool(tool_id_or_name: str) -> dict[str, Any] | None:
    """Resolve stable ID or exact canonical name; presentation aliases do not authorize."""
    token = str(tool_id_or_name or "").strip()
    row = _resolve_target(token)
    return deepcopy(row) if row else None


def list_target_tools(*, workbench: str | None = None, status: str | None = None,
                      search: str | None = None) -> list[dict[str, Any]]:
    query = str(search or "").strip().casefold()
    result = []
    for row in TOOL_TARGETS:
        if workbench and row["workbench"] != workbench:
            continue
        if status and row["implementation_status"] != status:
            continue
        fields = (row["tool_id"], row["canonical_name"], *row.get("aliases", []), row["workbench"],
                  row["existing_module_or_route"], row["calculation_or_action"])
        if query and query not in " ".join(map(str, fields)).casefold():
            continue
        result.append(deepcopy(row))
    return result


def target_tool_access_decision(tool_id_or_name: str, current_tier: str | None) -> dict[str, Any]:
    """Fail closed for unknown tool, tier or policy; Research Pack is not Enterprise Plus."""
    token = str(tool_id_or_name or "").strip()
    row = _resolve_target(token)
    tier = _normalize_known_tier(current_tier)
    if row is None:
        return {"allowed": False, "reason": "UNRESOLVED_TOOL", "tool_id": None,
                "required_tier": None, "current_tier": tier}
    if tier is None:
        return {"allowed": False, "reason": "UNRESOLVED_TIER", "tool_id": row["tool_id"],
                "required_tier": row["target_minimum_tier"], "current_tier": None}
    required = row.get("target_minimum_tier")
    if required not in TOOL_TIER_ORDER:
        return {"allowed": False, "reason": "UNRESOLVED_POLICY", "tool_id": row["tool_id"],
                "required_tier": required, "current_tier": tier}
    from shoir_tier_capabilities import tier_allows
    allowed = tier_allows(tier, required)
    return {"allowed": allowed, "reason": "ALLOWED" if allowed else "TIER_REQUIRED",
            "tool_id": row["tool_id"], "required_tier": required, "current_tier": tier}


def target_tool_execution_decision(tool_id_or_name: str, current_tier: str | None) -> dict[str, Any]:
    """Tier entitlement is necessary but never sufficient without verified readiness."""
    decision = target_tool_access_decision(tool_id_or_name, current_tier)
    if not decision["allowed"]:
        return {**decision, "executable": False}
    row = _BY_ID[decision["tool_id"]]
    executable = row["implementation_status"] == "VERIFIED_WORKING"
    return {**decision, "executable": executable,
            "reason": "VERIFIED_WORKING" if executable else "NOT_END_TO_END_VERIFIED"}


def audit_target_tool_registry() -> dict[str, Any]:
    required_fields = ("tool_id","canonical_name","aliases","workbench","target_minimum_tier",
                       "existing_module_or_route","implementation_status","calculation_or_action",
                       "input_contract","output_contract","source_files","remaining_gap",
                       "persistence_scope","external_dependency","entitlement_enforcement_points",
                       "unit_test_id","integration_test_id","browser_test_id",
                       "acceptance_gate_id","evidence_state")
    ids = [row.get("tool_id","") for row in TOOL_TARGETS]
    missing, bad_status, bad_tier, bad_workbench = [], [], [], []
    for row in TOOL_TARGETS:
        for field in required_fields:
            value = row.get(field)
            if field == "aliases":
                if not isinstance(value, list) or any(not isinstance(alias, str) or not alias.strip() for alias in value):
                    missing.append({"tool_id":row.get("tool_id"),"field":field})
            elif not value:
                missing.append({"tool_id":row.get("tool_id"),"field":field})
        if row.get("implementation_status") not in TOOL_STATUSES: bad_status.append(row.get("tool_id"))
        if row.get("target_minimum_tier") not in TOOL_TIER_ORDER: bad_tier.append(row.get("tool_id"))
        if row.get("workbench") not in WORKBENCHES: bad_workbench.append(row.get("tool_id"))
    counts = {status: sum(row.get("implementation_status") == status for row in TOOL_TARGETS)
              for status in sorted(TOOL_STATUSES)}
    return {"count":len(TOOL_TARGETS),"unique_id_count":len(set(ids)),
            "duplicate_ids":sorted({x for x in ids if ids.count(x)>1}),
            "missing_fields":missing,"invalid_statuses":bad_status,"invalid_tiers":bad_tier,
            "invalid_workbenches":bad_workbench,"status_counts":counts,
            "ready_for_execution_count":counts.get("VERIFIED_WORKING",0)}
